style.css:
@-moz-document domain("drive.google.com") {
/* === GLOBAL DARK BACKGROUND === */
body, html {
    background: linear-gradient(135deg, #000000 0%, #2c2c2c 25%, #1a1a1a 50%, #3a3a3a 75%, #000000 100%) !important;
    color: #ffffff !important;
    font-family: 'Segoe UI', -apple-system, system-ui, sans-serif !important;
}

/* === MAIN CONTAINER === */
.gb_df, .gb_eg, .gb_bg {
    background: linear-gradient(145deg, #000000 0%, #2c2c2c 50%, #1a1a1a 100%) !important;
    border: 1px solid #4a4a4a !important;
}

/* === NAVIGATION HEADER === */
.gb_jd, .gb_kd, .gb_md {
    background: linear-gradient(90deg, #000000 0%, #2c2c2c 100%) !important;
    border-bottom: 2px solid #ff6b35 !important;
    backdrop-filter: blur(15px) !important;
    box-shadow: 0 2px 10px rgba(255, 107, 53, 0.3) !important;
}

/* === SIDEBAR === */
.h-sb-Al, .a-Zb-Zb, .a-s-fa-Ha-pa {
    background: linear-gradient(180deg, #0d0d0d 0%, #2c2c2c 50%, #1a1a1a 100%) !important;
    border-right: 2px solid #00ff88 !important;
    box-shadow: 2px 0 15px rgba(0, 255, 136, 0.2) !important;
}

/* === SIDEBAR ITEMS === */
.a-s-fa-Ha-pa .h-sb-kc, .a-s-fa-Ha-pa .h-sb-wc {
    color: #00ff88 !important;
    font-weight: 600 !important;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1) !important;
    text-shadow: 0 0 5px rgba(0, 255, 136, 0.3) !important;
}

.a-s-fa-Ha-pa .h-sb-kc:hover, .a-s-fa-Ha-pa .h-sb-wc:hover {
    background: linear-gradient(90deg, rgba(255, 20, 147, 0.2) 0%, rgba(0, 255, 136, 0.2) 100%) !important;
    color: #ff1493 !important;
    border-radius: 10px !important;
    box-shadow: 0 0 20px rgba(255, 20, 147, 0.4) !important;
    text-shadow: 0 0 10px rgba(255, 20, 147, 0.6) !important;
    transform: translateX(5px) !important;
}

/* === MAIN CONTENT AREA === */
.a-pb-T-Jw, .a-t-j, .a-t-j-T {
    background: linear-gradient(135deg, #000000 0%, #1a1a1a 25%, #2c2c2c 75%, #000000 100%) !important;
    color: #ffffff !important;
}

/* === FILE GRID === */
.a-u-B-Oc-f, .a-u-B-Oc-f-Fb {
    background: linear-gradient(145deg, #1a1a1a 0%, #2c2c2c 100%) !important;
    border: 2px solid #4a4a4a !important;
    border-radius: 15px !important;
    transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275) !important;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.5) !important;
}

.a-u-B-Oc-f:hover {
    background: linear-gradient(145deg, #2c2c2c 0%, #3a3a3a 100%) !important;
    border: 2px solid #ff6b35 !important;
    box-shadow: 0 10px 30px rgba(255, 107, 53, 0.4), 0 0 20px rgba(255, 107, 53, 0.2) !important;
    transform: translateY(-8px) scale(1.02) !important;
}

/* === FOLDER ICONS - VIBRANT COLORS === */
[data-tooltip*="folder"], .a-u-B-Oc-oa-k[data-tooltip*="folder"] {
    color: #ffd700 !important;
    filter: drop-shadow(0 0 8px rgba(255, 215, 0, 0.6)) !important;
}

/* === DOCUMENT ICONS - DIFFERENT COLORS === */
[data-tooltip*="doc"], [data-tooltip*="docx"] {
    color: #00bfff !important;
    filter: drop-shadow(0 0 8px rgba(0, 191, 255, 0.6)) !important;
}

[data-tooltip*="pdf"] {
    color: #ff4444 !important;
    filter: drop-shadow(0 0 8px rgba(255, 68, 68, 0.6)) !important;
}

[data-tooltip*="xls"], [data-tooltip*="xlsx"] {
    color: #00ff88 !important;
    filter: drop-shadow(0 0 8px rgba(0, 255, 136, 0.6)) !important;
}

[data-tooltip*="ppt"], [data-tooltip*="pptx"] {
    color: #ff6b35 !important;
    filter: drop-shadow(0 0 8px rgba(255, 107, 53, 0.6)) !important;
}

[data-tooltip*="img"], [data-tooltip*="jpg"], [data-tooltip*="png"] {
    color: #ff1493 !important;
    filter: drop-shadow(0 0 8px rgba(255, 20, 147, 0.6)) !important;
}

/* === FILE NAMES === */
.a-u-B-Oc-oa-k, .a-u-B-Oc-oa-k-f {
    color: #ffffff !important;
    font-weight: 600 !important;
    text-shadow: 0 1px 3px rgba(0, 0, 0, 0.8) !important;
}

/* === BUTTONS === */
.a-s-fa-Ha-pa-f-jb, button, .gb_Ra {
    background: linear-gradient(135deg, #2c2c2c 0%, #4a4a4a 100%) !important;
    border: 2px solid #00bfff !important;
    color: #00bfff !important;
    border-radius: 12px !important;
    transition: all 0.3s ease !important;
    font-weight: 600 !important;
    text-shadow: 0 0 5px rgba(0, 191, 255, 0.5) !important;
}

.a-s-fa-Ha-pa-f-jb:hover, button:hover, .gb_Ra:hover {
    background: linear-gradient(135deg, #00bfff22 0%, #ff149355 100%) !important;
    color: #ffffff !important;
    border: 2px solid #ff1493 !important;
    box-shadow: 0 0 25px rgba(255, 20, 147, 0.6) !important;
    transform: scale(1.08) translateY(-2px) !important;
    text-shadow: 0 0 10px rgba(255, 255, 255, 0.8) !important;
}

/* === CREATE BUTTON === */
.a-s-tb-r-Jw-atb, .gb_te {
    background: linear-gradient(135deg, #ff6b35 0%, #ff1493 50%, #ffd700 100%) !important;
    color: #000000 !important;
    border: none !important;
    border-radius: 30px !important;
    box-shadow: 0 8px 25px rgba(255, 107, 53, 0.5) !important;
    font-weight: 800 !important;
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.5) !important;
}

.a-s-tb-r-Jw-atb:hover {
    box-shadow: 0 12px 35px rgba(255, 20, 147, 0.7) !important;
    transform: translateY(-4px) scale(1.1) !important;
    background: linear-gradient(135deg, #ffd700 0%, #ff1493 50%, #00ff88 100%) !important;
}

/* === SEARCH BAR === */
.gb_Qe, .gb_Pe, input[type="text"] {
    background: linear-gradient(90deg, #1a1a1a 0%, #2c2c2c 100%) !important;
    border: 2px solid #00ff88 !important;
    color: #ffffff !important;
    border-radius: 25px !important;
    backdrop-filter: blur(10px) !important;
    box-shadow: inset 0 2px 5px rgba(0, 0, 0, 0.3) !important;
}

.gb_Qe:focus, .gb_Pe:focus, input[type="text"]:focus {
    border: 3px solid #ff6b35 !important;
    box-shadow: 0 0 20px rgba(255, 107, 53, 0.5), inset 0 2px 5px rgba(0, 0, 0, 0.3) !important;
    outline: none !important;
    color: #ff6b35 !important;
}

/* === DROPDOWN MENUS === */
.gb_ma, .gb_Ba, .a-s-Wg-rd {
    background: linear-gradient(135deg, #0d0d0d 0%, #2c2c2c 50%, #1a1a1a 100%) !important;
    border: 2px solid #ff1493 !important;
    border-radius: 15px !important;
    box-shadow: 0 15px 40px rgba(255, 20, 147, 0.3) !important;
}

/* === MENU ITEMS === */
.gb_ya, .gb_za, .a-s-Wg-rd-c {
    color: #00bfff !important;
    transition: all 0.2s ease !important;
    font-weight: 600 !important;
}

.gb_ya:hover, .gb_za:hover, .a-s-Wg-rd-c:hover {
    background: linear-gradient(90deg, rgba(255, 215, 0, 0.2) 0%, rgba(0, 255, 136, 0.2) 100%) !important;
    color: #ffd700 !important;
    text-shadow: 0 0 8px rgba(255, 215, 0, 0.6) !important;
}

/* === ICONS - MULTI-COLOR === */
.gb_yc, .gb_8c, svg {
    filter: brightness(0) saturate(100%) invert(47%) sepia(96%) saturate(1000%) hue-rotate(180deg) brightness(2) !important;
}

/* Specific icon colors */
svg[data-icon="folder"] {
    filter: brightness(0) saturate(100%) invert(77%) sepia(85%) saturate(6900%) hue-rotate(2deg) brightness(107%) contrast(107%) !important;
}

svg[data-icon="file"] {
    filter: brightness(0) saturate(100%) invert(47%) sepia(96%) saturate(1000%) hue-rotate(180deg) brightness(2) !important;
}

/* === SCROLLBARS - RAINBOW GRADIENT === */
::-webkit-scrollbar {
    width: 12px !important;
    background: linear-gradient(180deg, #000000 0%, #2c2c2c 100%) !important;
    border-radius: 6px !important;
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, #ff6b35 0%, #ff1493 25%, #00bfff 50%, #00ff88 75%, #ffd700 100%) !important;
    border-radius: 6px !important;
    border: 1px solid #000000 !important;
}

::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, #ffd700 0%, #00ff88 25%, #00bfff 50%, #ff1493 75%, #ff6b35 100%) !important;
    box-shadow: 0 0 10px rgba(255, 255, 255, 0.5) !important;
}

::-webkit-scrollbar-corner {
    background: #000000 !important;
}

/* === TABS - HIGH CONTRAST === */
.gb_ic, .gb_jc, .gb_gc {
    background: linear-gradient(90deg, #1a1a1a 0%, #2c2c2c 100%) !important;
    border: 2px solid #00ff88 !important;
    color: #00ff88 !important;
    border-radius: 8px 8px 0 0 !important;
    font-weight: 700 !important;
}

.gb_ic:hover, .gb_jc:hover, .gb_gc:hover {
    background: linear-gradient(90deg, #ff1493 0%, #ff6b35 100%) !important;
    color: #ffffff !important;
    border-color: #ffd700 !important;
    box-shadow: 0 -3px 10px rgba(255, 215, 0, 0.4) !important;
}

/* === CUSTOM CURSOR === */
* {
    cursor: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 20 20"><circle cx="10" cy="10" r="8" fill="%23ff1493" stroke="%23ffffff" stroke-width="2"/></svg>'), auto !important;
}

button, a, [role="button"] {
    cursor: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 20 20"><polygon points="10,2 18,18 10,14 2,18" fill="%2300ff88" stroke="%23ffffff" stroke-width="1"/></svg>'), pointer !important;
}

/* === BREADCRUMBS === */
.a-pb-T-Jw-atb-ca, .a-pb-T-Jw-atb-ca-T {
    color: #ffd700 !important;
    font-weight: 600 !important;
    text-shadow: 0 0 5px rgba(255, 215, 0, 0.5) !important;
}

/* === STATUS BAR === */
.a-t-j-Pa, .a-t-j-Pa-T {
    background: linear-gradient(90deg, #000000 0%, #2c2c2c 100%) !important;
    border-top: 2px solid #00bfff !important;
    color: #00bfff !important;
    font-weight: 600 !important;
}

/* === MODAL DIALOGS === */
.a-Ud-Jb, .gb_g {
    background: linear-gradient(135deg, #0d0d0d 0%, #2c2c2c 50%, #1a1a1a 100%) !important;
    border: 3px solid transparent !important;
    border-image: linear-gradient(45deg, #ff6b35, #ff1493, #00bfff, #00ff88, #ffd700) 1 !important;
    border-radius: 20px !important;
    box-shadow: 0 25px 60px rgba(0, 0, 0, 0.8) !important;
}

/* === PROGRESS BARS === */
.a-s-tb-r-Jw-atb-progress {
    background: linear-gradient(90deg, #ff6b35 0%, #ff1493 25%, #00bfff 50%, #00ff88 75%, #ffd700 100%) !important;
    border-radius: 15px !important;
    height: 8px !important;
    box-shadow: 0 0 10px rgba(255, 255, 255, 0.3) !important;
}

/* === SELECTION HIGHLIGHT === */
::selection {
    background: linear-gradient(90deg, rgba(255, 20, 147, 0.4) 0%, rgba(0, 255, 136, 0.4) 100%) !important;
    color: #ffffff !important;
}

/* === ANIMATED GLOW EFFECTS === */
@keyframes rainbowGlow {
    0% { box-shadow: 0 0 20px #ff6b35; }
    20% { box-shadow: 0 0 20px #ff1493; }
    40% { box-shadow: 0 0 20px #00bfff; }
    60% { box-shadow: 0 0 20px #00ff88; }
    80% { box-shadow: 0 0 20px #ffd700; }
    100% { box-shadow: 0 0 20px #ff6b35; }
}

.a-s-tb-r-Jw-atb {
    animation: rainbowGlow 3s ease-in-out infinite !important;
}

/* === LOADING SPINNERS === */
.gb_tg {
    border: 3px solid transparent !important;
    border-top: 3px solid #ff1493 !important;
    border-right: 3px solid #00ff88 !important;
    border-bottom: 3px solid #ffd700 !important;
    border-left: 3px solid #00bfff !important;
}

/* === CONTEXT MENU STYLING === */
.gb_Pa, .gb_Qa {
    background: linear-gradient(135deg, #000000 0%, #2c2c2c 100%) !important;
    border: 2px solid #ff6b35 !important;
    border-radius: 12px !important;
    box-shadow: 0 10px 30px rgba(255, 107, 53, 0.4) !important;
}

/* === NOTIFICATION STYLING === */
.gb_xa, .gb_wa {
    background: linear-gradient(90deg, #1a1a1a 0%, #2c2c2c 100%) !important;
    border: 2px solid #ffd700 !important;
    color: #ffd700 !important;
    border-radius: 10px !important;
    box-shadow: 0 5px 15px rgba(255, 215, 0, 0.3) !important;
}
}
